int graphMaxDegree_38(const vector<vector<int>>& adj) { int mx = 0; for (int u = 0; u < (int)adj.size(); ++u) if ((int)adj[u].size() > mx) mx = adj[u].size(); return mx; }
int bfsDistance_38(const vector<vector<int>>& adj, int src) { int V = adj.size(); vector<int> dist(V, -1); queue<int> q; dist[src] = 0; q.push(src); while (!q.empty()) { int u = q.front(); q.pop(); for (int v2 : adj[u]) if (dist[v2] == -1) { dist[v2] = dist[u] + 1; q.push(v2); } } int mx = 0; for (int i = 0; i < V; ++i) if (dist[i] > mx) mx = dist[i]; return mx; }
int reachableCountBfs_38(const vector<vector<int>>& adj, int src) { int V = adj.size(), cnt = 0; vector<bool> seen(V, false); queue<int> q; seen[src] = true; q.push(src); while (!q.empty()) { int u = q.front(); q.pop(); ++cnt; for (int v2 : adj[u]) if (!seen[v2]) { seen[v2] = true; q.push(v2); } } return cnt; }
bool bipartiteCheckBfs_38(const vector<vector<int>>& adj) { int V = adj.size(); vector<int> vis(V, 0); queue<int> q; for (int i = 0; i < V; ++i) { if (vis[i] != 0) continue; vis[i] = 1; q.push(i); while (!q.empty()) { int u = q.front(); q.pop(); for (int v2 : adj[u]) { if (vis[v2] == 0) { vis[v2] = -vis[u]; q.push(v2); } else if (vis[v2] == vis[u]) return false; } } } return true; }
vector<int> kahnTopoSort_38(const vector<vector<int>>& adj) { int V = adj.size(); vector<int> deg(V, 0); for (int u = 0; u < V; ++u) for (int v2 : adj[u]) ++deg[v2]; queue<int> q; for (int i = 0; i < V; ++i) if (deg[i] == 0) q.push(i); vector<int> order; while (!q.empty()) { int u = q.front(); q.pop(); order.push_back(u); for (int v2 : adj[u]) if (--deg[v2] == 0) q.push(v2); } return order; }
